<?php
function opportunityRows($pdo,$uid,$kind){$q=$pdo->prepare('SELECT id,payload,created_at FROM aulieata_records WHERE user_id=? AND kind=? AND archived=0 ORDER BY id DESC LIMIT 500');$q->execute([$uid,$kind]);return array_map(function($r){$r['data']=json_decode($r['payload'],true)?:[];unset($r['payload']);return $r;},$q->fetchAll());}
function localBusinessDay(){return (new DateTime('now',new DateTimeZone('Asia/Qyzylorda')))->format('Y-m-d');}
function validBusinessDate($s){$d=DateTime::createFromFormat('!Y-m-d',(string)$s);return $d&&$d->format('Y-m-d')===$s;}
function scanBusinessSignals($pdo,$uid){$today=localBusinessDay();$out=[];foreach(opsBatchRows($pdo,$uid) as $r){$d=$r['data'];$d['quantity']=$r['free'];if((float)($d['quantity']??0)<=0)continue;$expiry=$d['expires_on']??'';$days=$expiry?(int)round((strtotime($expiry)-strtotime($today))/86400):null;$age=(int)round((strtotime($today)-strtotime($d['received_on']??$today))/86400);$base=['record_id'=>(int)$r['id'],'kind'=>'stock','name'=>$d['name'],'quantity'=>(float)$d['quantity'],'price'=>(float)$d['price'],'cost'=>(float)$d['cost'],'expires_on'=>$expiry,'days_left'=>$days];if($days!==null&&$days<0)$out[]=$base+['signal'=>'expired','title'=>'Срок истёк — исключить из продажи','eligible'=>false];elseif($days!==null&&$days<=7)$out[]=$base+['signal'=>'expiry','title'=>$days===0?'Срок истекает сегодня':'До окончания срока: '.$days.' дн.','eligible'=>($d['condition']??'blocked')==='safe'];elseif($age>=30)$out[]=$base+['signal'=>'aging','title'=>'Партия хранится '.$age.' дн. — проверить оборачиваемость','eligible'=>($d['condition']??'blocked')==='safe'];if((float)$d['quantity']<=(float)($d['min_stock']??0))$out[]=$base+['signal'=>'low_stock','title'=>'Остаток на уровне минимума — проверить закупку','eligible'=>false];}
foreach(opportunityRows($pdo,$uid,'business_capacity') as $r){$d=$r['data'];$days=(int)round((strtotime($d['date'])-strtotime($today))/86400);if($days>=0&&$days<=7&&(float)$d['quantity']>0)$out[]=['record_id'=>(int)$r['id'],'kind'=>'capacity','name'=>$d['name'],'quantity'=>(float)$d['quantity'],'price'=>(float)$d['price'],'cost'=>(float)$d['cost'],'expires_on'=>$d['date'],'days_left'=>$days,'signal'=>'capacity','title'=>'Свободные места / часы: '.$d['quantity'].' · '.$d['date'],'eligible'=>true];}return $out;}
function promotionCandidates($signals,$margin){$out=[];$seen=[];foreach($signals as $s){if(!$s['eligible']||isset($seen[$s['record_id']])||$s['cost']<=0||$s['price']<=$s['cost'])continue;$seen[$s['record_id']]=true;$floor=ceil($s['cost']/(1-$margin/100)*100)/100;if($floor>=$s['price'])continue;$discount=($s['days_left']!==null&&$s['days_left']<=1)?25:15;$price=max($floor,round($s['price']*(1-$discount/100),2));if($price>=$s['price'])continue;$out[]=$s+['floor_price'=>$floor,'offer_price'=>$price,'discount_percent'=>round((1-$price/$s['price'])*100,1),'gross_margin_percent'=>round((1-$s['cost']/$price)*100,1)];}return array_slice($out,0,12);}
function publicBusinessPromotions($pdo,$uid){if(businessProfile($pdo,$uid)['type']==='medical')return [];$today=localBusinessDay();$eligible=[];foreach(scanBusinessSignals($pdo,$uid) as $s)if($s['eligible'])$eligible[$s['record_id']]=$s;$out=[];foreach(opportunityRows($pdo,$uid,'promotion_drafts') as $r){$d=$r['data'];$source=$eligible[$d['source_id']??0]??null;if(($d['status']??'')!=='published'||!$source||($d['valid_until']??'')<$today||$source['quantity']<=0||$d['offer_price']<ceil($source['cost']/(1-($d['min_margin']??20)/100)*100)/100)continue;$out[]=['id'=>(int)$r['id'],'title'=>$d['name'],'item'=>$source['name'],'price'=>$d['offer_price'],'valid_until'=>!empty($source['expires_on'])?min($d['valid_until'],$source['expires_on']):$d['valid_until'],'quantity_limit'=>min($source['quantity'],$d['quantity_limit']),'text'=>$d['copy']];}return array_slice($out,0,20);}
