'toyhana'=>['Банкетные залы',['Свободные даты зала','Банкетные пакеты по бюджету','Партии продуктов и себестоимость'],true],
'services'=>['Бытовые услуги',['Свободные часы специалистов','Пакеты услуг','Контроль задач и расходников'],true]
];$k=$kits[$type]??$kits['services'];return ['title'=>$k[0],'ideas'=>$k[1],'stock'=>$k[2]];}
function cleanOpportunityResource($kind,$d){if(!is_array($d))throw new RuntimeException('Проверьте данные');$name=mb_substr(trim((string)($d['name']??'')),0,180);$qty=filter_var($d['quantity']??null,FILTER_VALIDATE_FLOAT);$price=filter_var($d['price']??0,FILTER_VALIDATE_FLOAT);$cost=filter_var($d['cost']??0,FILTER_VALIDATE_FLOAT);if(!$name||$qty===false||$qty<0||$qty>100000000||$price===false||$price<0||$price>1000000000||$cost===false||$cost<0||$cost>1000000000)throw new RuntimeException('Нужны название, неотрицательные остаток, цена и себестоимость');$r=['item_id'=>(int)($d['item_id']??0),'name'=>$name,'quantity'=>round($qty,3),'price'=>round($price,2),'cost'=>round($cost,2),'unit'=>mb_substr(trim((string)($d['unit']??'шт.')),0,30)?:'шт.'];if($kind==='stock_batches'){$expiry=normalizeBusinessImportDate($d['expires_on']??'');$received=normalizeBusinessImportDate($d['received_on']??localBusinessDay());if(($expiry&&!validBusinessDate($expiry))||!validBusinessDate($received)||$received>localBusinessDay())throw new RuntimeException('Проверьте срок и дату поступления');$min=filter_var($d['min_stock']??0,FILTER_VALIDATE_FLOAT);if($min===false||$min<0)throw new RuntimeException('Минимальный остаток должен быть неотрицательным');return $r+['expires_on'=>$expiry,'received_on'=>$received,'batch'=>mb_substr(trim((string)($d['batch']??'')),0,100),'min_stock'=>$min,'condition'=>($d['condition']??'blocked')==='safe'?'safe':'blocked'];}$date=normalizeBusinessImportDate($d['date']??'');if(!validBusinessDate($date)||$date<localBusinessDay())throw new RuntimeException('Выберите текущую или будущую дату');return $r+['date'=>$date,'note'=>mb_substr(trim((string)($d['note']??'')),0,1000)];}

function buildPromotionDrafts($pdo,$uid,$margin,$businessProfile,$cfg){$signals=scanBusinessSignals($pdo,$uid);$candidates=promotionCandidates($signals,$margin);if($businessProfile['type']==='medical')throw new RuntimeException('Для медицинской сферы автоматические товарные акции отключены');if(!$candidates)throw new RuntimeException('Нет подходящих ресурсов: проверьте остатки, условия хранения, цену, себестоимость и маржу');
$json=platformAI($cfg,'Ты маркетолог малого бизнеса. Предложи до 5 оригинальных и выполнимых акций по переданным ресурсам. Верни JSON {"ideas":[{"source_id":123,"title":"название идеи","mechanic":"механика без новых числовых обещаний","copy":"текст анонса без цены и дат: они будут добавлены отдельно","steps":["шаг запуска","шаг проверки"]}]}. Используй только source_id из candidates. Не придумывай товары, спрос, отзывы, доставку, наличие или партнёров. Цены, скидки, лимиты и сроки задаёт сервер — не добавляй свои числа в анонс. Не продлевай срок годности и не предлагай продажу просроченного, маскировку дефектов или изменение маркировки. Не обещай гарантированный эффект. Для кафе это может быть набор, для свободных часов — предложение на конкретное время, для магазина — тематический комплект; дополнительные компоненты только из реальных данных.',json_encode(['business'=>$businessProfile,'sector'=>sectorKit($businessProfile['type']),'candidates'=>$candidates],JSON_UNESCAPED_UNICODE),3000);
$byId=[];foreach($candidates as $c)$byId[$c['record_id']]=$c;$ids=[];$seen=[];foreach(array_slice($json['ideas']??[],0,5) as $idea){$c=$byId[(int)($idea['source_id']??0)]??null;if(!$c||isset($seen[$c['record_id']]))continue;$seen[$c['record_id']]=true;$until=$c['expires_on']?:date('Y-m-d',strtotime(localBusinessDay().' +7 days'));$d=['name'=>opsText($idea['title']??'Предложение',180),'source_id'=>$c['record_id'],'source_kind'=>$c['kind'],'item'=>$c['name'],'offer_price'=>$c['offer_price'],'original_price'=>$c['price'],'cost'=>$c['cost'],'min_margin'=>$margin,'gross_margin_percent'=>$c['gross_margin_percent'],'discount_percent'=>$c['discount_percent'],'quantity_limit'=>$c['quantity'],'valid_until'=>$until,'mechanic'=>opsText($idea['mechanic']??'',2000),'copy'=>opsText($idea['copy']??'',3000),'steps'=>array_map(fn($x)=>opsText($x,500),array_slice($idea['steps']??[],0,6)),'status'=>'draft'];$ids[]=platformRecord($pdo,$uid,'promotion_drafts',$d);}if(!$ids)throw new RuntimeException('ИИ не подготовил подходящие идеи');return $ids;}

function normalizeBusinessImportDate($v){$v=trim((string)$v);if(preg_match('/^([0-9]{2})[.]([0-9]{2})[.]([0-9]{4})$/D',$v,$m))return $m[3].'-'.$m[2].'-'.$m[1];return $v;}
